INSERT INTO cf_recon.cf_image (image_id, uploaded_at, filename, meta, first_seen_at, last_seen_at) SELECT cf_id, uploaded, filename, meta, COALESCE(ingested_at, now()), COALESCE(ingested_at, now()) FROM public._cf_images_audit ON CONFLICT (image_id) DO UPDATE SET last_seen_at = EXCLUDED.last_seen_at, filename = COALESCE(EXCLUDED.filename, cf_recon.cf_image.filename), meta = COALESCE(EXCLUDED.meta, cf_recon.cf_image.meta);;
